///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_fnFileDown
 * @description fn File Down 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnFileDown = async function (action) {
    try { return await $c.data.downFile(action ?? "/support/comSprtSvcFileDownload.do", "", ($c.util.getComponent("dma_fnFileDownReq") ? $c.util.getComponent("dma_fnFileDownReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name fnSearch
 * @description fn Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearch = async function () {
    $("input[name='method']").val("comSprtSvcApplList");
    $("form[name='comSprtSvcFrm']").attr("method", "post");
    $("form[name='comSprtSvcFrm']").attr("onsubmit", "");
    const nr = await scwin.tx_fnSearch();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil16601/jldfil16601.xml", { "method": "comSprtSvcApplList" });
    }
};

/**
 * @method
 * @name doubleSubmitCheck
 * @description double Submit Check 처리
 * @returns {void}
 * @hidden N
 */
scwin.doubleSubmitCheck = function () {
    if (scwin.doubleSubmitFlag) {
        return scwin.doubleSubmitFlag;
    } else {
        scwin.doubleSubmitFlag = true;
        return false;
    }
};

/**
 * @method
 * @name fnRegister
 * @description fn Register 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnRegister = async function () {
    const chrgNm = $("input[name='chrgNm']");
    if (chrgNm == null || chrgNm == null) {
        await $c.win.alert("참석자 정보가 없습니다.");
        return;
    }
    for (let i = 0; i < chrgNm.length; i++) {
        if (chrgNm.eq(0).attr("value") == null || chrgNm.eq(0).attr("value") === "") {
            await $c.win.alert("참석자 1 성명을 입력하세요.");
            /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
            return;
        }
        if ($("input[name='jobtitlNm']").eq(0).attr("value") == null || $("input[name='jobtitlNm']").eq(0).attr("value") === "") {
            await $c.win.alert("참석자 1 직위를 입력하세요.");
            /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
            return;
        }
        if ($("input[name='telNo']").eq(0).attr("value") == null || $("input[name='telNo']").eq(0).attr("value") === "") {
            await $c.win.alert("참석자 1 연락처를 입력하세요.");
            /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
            return;
        }
        if ($("input[name='telNo']").eq(i).attr("value") !== "") {
            if (scwin.fnTelNoCheck($("input[name='telNo']").eq(i).attr("value"))) {
                await $c.win.alert("참석자 " + (i + 1) + " 연락처 형식이 틀렸습니다.\nex)02-0000-0000");
                /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
                return;
            }
        }
        if ($("input[name='cellphoneNo']").eq(0).attr("value") == null || $("input[name='cellphoneNo']").eq(0).attr("value") === "") {
            await $c.win.alert("참석자 1 핸드폰을 입력하세요.");
            /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
            return;
        }
        if ($("input[name='cellphoneNo']").eq(i).attr("value") !== "") {
            if (scwin.fnCellPhoneCheck($("input[name='cellphoneNo']").eq(i).attr("value"))) {
                await $c.win.alert("참석자 " + (i + 1) + " 핸드폰 형식이 틀렸습니다.\nex)010-0000-0000");
                /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
                return;
            }
        }
        if ($("input[name='email']").eq(0).attr("value") == null || $("input[name='email']").eq(0).attr("value") === "") {
            await $c.win.alert("참석자 1 이메일을 입력하세요.");
            /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
            return;
        }
        if ($("input[name='email']").eq(i).attr("value") !== "") {
            if (scwin.fnEmailCheck($("input[name='email']").eq(i).attr("value"))) {
                await $c.win.alert("참석자 " + (i + 1) + " 이메일 형식이 틀렸습니다.");
                /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
                return;
            }
        }
    }
    const pCnt = await scwin.fnApplPersCntChk();
    if (pCnt === 0) {
        await $c.win.alert('신청가능한 정원수를 초과하였습니다.\n다음에 신청해주세요.');
        return;
    } else {
        let cSize = 0;
        for (let i = 0; i < chrgNm.length; i++) {
            if (chrgNm.eq(i).attr("value") != null && chrgNm.eq(i).attr("value") !== "") {
                cSize++;
            }
        }
        if ((pCnt - cSize) < 0) {
            await $c.win.alert('신청가능한 정원수를 초과하였습니다.\n참석자를 ' + -(pCnt - cSize) + '명 줄이세요.');
            return;
        }
    }
    if ($("#ipt_perInfoChk1").is(":checked") !== true) {
        await $c.win.alert("개인정보 수집 및 이용에 동의해야 신청가능합니다.");
        $c.util.getComponent("ipt_perInfoChk1").focus();
        return;
    }
    if (scwin.doubleSubmitCheck()) {
        return;
    }
    $("input[name='method']").val("comSprtSvcApplWrite");
    $("form[name='comSprtSvcFrm']").attr("method", "post");
    $("form[name='comSprtSvcFrm']").attr("onsubmit", "");
    await scwin.tx_fnRegister();
};

/**
 * @method
 * @name fnTelNoCheck
 * @description fn Tel No Check 처리
 * @param {*} ipt_telNo ipt_telNo
 * @returns {void}
 * @hidden N
 */
scwin.fnTelNoCheck = function (ipt_telNo) {
    const regTelNo = /^(0[2-8][0-5]?)-?([1-9]{1}[0-9]{2,3})-?([0-9]{4})$/;
    if (!regTelNo.test(ipt_telNo)) {
        return true;
    }
    return false;
};

/**
 * @method
 * @name fnCellPhoneCheck
 * @description fn Cell Phone Check 처리
 * @param {*} cellPhoneNum cellPhoneNum
 * @returns {void}
 * @hidden N
 */
scwin.fnCellPhoneCheck = function (cellPhoneNum) {
    const regPhone = /(01[0|1|6|7|8|9])[-](\d{3}|\d{4})[-](\d{4}$)/g;
    if (!regPhone.test(cellPhoneNum)) {
        return true;
    }
    return false;
};

/**
 * @method
 * @name fnEmailCheck
 * @description fn Email Check 처리
 * @param {*} ipt_email ipt_email
 * @returns {void}
 * @hidden N
 */
scwin.fnEmailCheck = function (ipt_email) {
    const mailexp = /^[_a-zA-Z0-9-\.]+@[\.a-zA-Z0-9-]+\.[a-zA-Z]+$/;
    if (!mailexp.test(ipt_email)) {
        return true;
    }
    return false;
};

/**
 * @method
 * @name fnFileDown
 * @description fn File Down 처리
 * @param {String} contnId contnId
 * @param {*} contnAttachSeq contnAttachSeq
 * @param {String} attachFileNm attachFileNm
 * @param {*} wrtDdtm wrtDdtm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnFileDown = async function (contnId, contnAttachSeq, attachFileNm, wrtDdtm) {
    $c.util.getComponent('dma_fnSearchReq').set('method', 'comSprtSvcAttachFile');
    $c.util.getComponent('dma_fnSearchReq').set('contnId', contnId);
    $c.util.getComponent('dma_fnSearchReq').set('contnAttachSeq', contnAttachSeq);
    $c.util.getComponent('dma_fnSearchReq').set('attachFileNm', attachFileNm);
    $c.util.getComponent('dma_fnSearchReq').set('wrtDdtm', wrtDdtm);
    await scwin.tx_fnFileDown('/support/comSprtSvcFileDownload.do');
};

// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)

/**
 * @method
 * @name fnApplPersCntChk_done
 * @description fn Appl Pers Cnt Chk done 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.fnApplPersCntChk_done = function (data) {
    scwin.result = (typeof data === "string" ? JSON.parse(data) : data);
    pCnt = scwin.result.returnVal;
};

/**
 * @method
 * @name fnApplPersCntChk
 * @description fn Appl Pers Cnt Chk 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnApplPersCntChk = async function () {
    const r = await scwin.tx_fnApplPersCntChk();
    try {
        scwin.fnApplPersCntChk_done.call(window, JSON.stringify((r && r.responseJSON && (r.responseJSON.body != null ? r.responseJSON.body : r.responseJSON)) || {}));
    }
    catch (_se) {
        await $c.exception.handleError(_se, { notify: 'none', context: 'jldfil16603.fnApplPersCntChk' });
    }
    return r;
};
